// SHARED PAGE SHELL
// ──────────────────────────────────────────────────────────────────────────────
function PageShell({ title, sub, action, children }) {
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
      <div style={{ padding: '18px 24px 14px', borderBottom: '1px solid var(--bv-bd)', background: 'var(--bv-bg2)', flexShrink: 0, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <div style={{ fontSize: 20, fontWeight: 600 }}>{title}</div>
          {sub && <div style={{ fontSize: 12, color: 'var(--bv-txt2)', marginTop: 3 }}>{sub}</div>}
        </div>
        {action}
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '20px 24px', display: 'flex', flexDirection: 'column', gap: 16 }}>
        {children}
      </div>
    </div>
  );
}

export function SecondaryDCPage() {
  const [data,    setData]    = useState(null);
  const [loading, setLoading] = useState(true);
  const [error,   setError]   = useState(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      // Uses /api/fs/secondary-mount — a separate endpoint for the secondary DC
      // Falls back to primary-mount with mount param if secondary-mount not yet added
      const token = localStorage.getItem('bv_token');
      const res = await fetch('/api/fs/secondary-mount', {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.status === 404) {
        // Endpoint not yet added — show "not configured" state
        setData({ notConfigured: true });
      } else if (res.ok) {
        const json = await res.json();
        setData(json);
      } else {
        setError('Failed to load secondary DC data');
      }
    } catch (e) {
      setError(e.message);
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const storage = data?.storage || {};
  const pct = parseInt(storage.usePercent) || 0;
  const barColor = pct >= 90 ? 'var(--bv-red)' : pct >= 80 ? 'var(--bv-amber)' : 'var(--bv-green)';

  // Detect truly empty: mounted but no backup files at all
  const tree = data?.tree || [];
  const totalFiles = tree.reduce((sum, f) => sum + (f.totalFiles || 0), 0);
  const hasData = totalFiles > 0;

  return (
    <PageShell
      title="Secondary DC Storage"
      sub={<>Rsync mirror: <span style={{ color:'var(--bv-cyan)', fontFamily:'monospace' }}>10.180.0.130</span> → <span style={{ color:'var(--bv-green)', fontFamily:'monospace' }}>/secondary-db-backup</span></>}
      action={<button onClick={load} style={{ display:'flex', alignItems:'center', gap:5, padding:'6px 13px', borderRadius:8, border:'1px solid var(--bv-bd2)', background:'var(--bv-bg4)', color:'var(--bv-txt)', fontSize:12, cursor:'pointer' }}><i className="ti ti-refresh" aria-hidden="true"/> Refresh</button>}
    >
      {/* Storage stats — only show if we have disk info */}
      {storage.size && (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12 }}>
          {[
            { icon:'server-2', label:'Total Pool',            value: storage.size,        color:'var(--bv-cyan)', bg:'var(--bv-cyan-bg)' },
            { icon:'chart-bar', label:`Used (${storage.usePercent})`, value: storage.used, color: barColor,   bg:'var(--bv-bg3)', bar: true },
            { icon:'check',    label:'Free Space',            value: storage.avail,       color:'var(--bv-green)', bg:'var(--bv-green-dim)' },
          ].map(({ icon, label, value, color, bg, bar }) => (
            <div key={label} style={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)', borderRadius:12, padding:'14px 16px', display:'flex', alignItems:'center', gap:14 }}>
              <div style={{ width:42, height:42, borderRadius:10, background:bg, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                <i className={`ti ti-${icon}`} style={{ fontSize:20, color }} aria-hidden="true"/>
              </div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:10, color:'var(--bv-txt3)', letterSpacing:'.07em', textTransform:'uppercase', fontWeight:600, marginBottom:4 }}>{label}</div>
                <div style={{ fontSize:22, fontWeight:500, color }}>{value}</div>
                {bar && <div style={{ width:'100%', height:6, background:'var(--bv-bg4)', borderRadius:3, overflow:'hidden', marginTop:5 }}>
                  <div style={{ height:'100%', width:`${pct}%`, background:barColor, borderRadius:3 }}/>
                </div>}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Content area */}
      {loading ? (
        <div style={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)', borderRadius:12, padding:60, textAlign:'center', color:'var(--bv-txt3)' }}>
          <i className="ti ti-loader" style={{ fontSize:32, display:'block', marginBottom:10, animation:'bvspin .7s linear infinite' }} aria-hidden="true"/>
          Loading secondary DC...
        </div>
      ) : error ? (
        <div style={{ background:'var(--bv-red-dim)', border:'1px solid var(--bv-red)', borderRadius:12, padding:24, color:'var(--bv-red)', fontSize:13 }}>
          <i className="ti ti-alert-triangle" style={{ marginRight:8 }} aria-hidden="true"/>
          {error}
        </div>
      ) : data?.notConfigured ? (
        <div style={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)', borderRadius:12, padding:48, textAlign:'center', color:'var(--bv-txt3)' }}>
          <i className="ti ti-server-off" style={{ fontSize:42, display:'block', marginBottom:14, color:'var(--bv-bd2)' }} aria-hidden="true"/>
          <div style={{ fontSize:15, fontWeight:500, color:'var(--bv-txt2)', marginBottom:8 }}>Secondary DC not configured</div>
          <div style={{ fontSize:12 }}>Add <code style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>/api/fs/secondary-mount</code> route in your backend,<br/>or mount the secondary DC at <code style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>/secondary-db-backup</code></div>
        </div>
      ) : !hasData ? (
        <div style={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)', borderRadius:12, padding:48, textAlign:'center', color:'var(--bv-txt3)' }}>
          <i className="ti ti-database-off" style={{ fontSize:42, display:'block', marginBottom:14, color:'var(--bv-bd2)' }} aria-hidden="true"/>
          <div style={{ fontSize:15, fontWeight:500, color:'var(--bv-txt2)', marginBottom:8 }}>No data available</div>
          <div style={{ fontSize:12 }}>Secondary DC is mounted at <code style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>/secondary-db-backup</code> but contains no backup files yet.<br/>
          Backups will appear here once the first rsync sync runs.</div>
        </div>
      ) : (
        <div style={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)', borderRadius:12, padding:16 }}>
          <div style={{ fontSize:11, fontWeight:600, color:'var(--bv-txt2)', letterSpacing:'.06em', textTransform:'uppercase', marginBottom:12 }}>Repository hierarchy · {totalFiles} total files</div>
          <div style={{ display:'flex', flexDirection:'column', gap:1 }}>
            {tree.filter(f => f.totalFiles > 0).map(folder => (
              <div key={folder.id} style={{ display:'flex', alignItems:'center', gap:10, padding:'9px 14px', background:'var(--bv-bg3)', border:'1px solid var(--bv-bd)', borderRadius:8 }}>
                <i className="ti ti-folder-filled" style={{ fontSize:15, color:'var(--bv-amber)' }} aria-hidden="true"/>
                <div style={{ flex:1, fontSize:13, fontWeight:500, color:'var(--bv-txt)' }}>{folder.folderName}</div>
                <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>{folder.totalFiles} files</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </PageShell>
  );
}
